    (r"ដោះស្រាយ $\sin x = 0$ ៖", r"$x = k\pi$", [r"$x = 2k\pi$", r"$x = \dfrac{\pi}{2} + k\pi$", r"$x = \dfrac{\pi}{2} + 2k\pi$"], r"ស៊ីនុសសូន្យត្រង់ពហុគុណនៃ $\pi$ ។"),
    (r"សមីការ $\sin x = 2$ ៖", r"គ្មានចម្លើយ", [r"$x = \dfrac{\pi}{2} + 2k\pi$", r"$x = \sin^{-1} 2$", r"មានចម្លើយតែមួយ"], r"$-1 \le \sin x \le 1$ ។"),
    (r"ដោះស្រាយ $\cos 2x = \cos x$ ៖", r"$x = \dfrac{2k\pi}{3}$", [r"$x = 2k\pi$", r"$x = k\pi$", r"$x = \dfrac{k\pi}{3}$"], r"$2x = x + 2k\pi$ ឬ $2x = -x + 2k\pi$ ៖ $x = 2k\pi$ ឬ $x = \dfrac{2k\pi}{3}$ (សំណុំទីពីររួមទាំងទីមួយ) ។"),
    (r"ដោះស្រាយ $\tan 3x = \sqrt{3}$ ៖", r"$x = \dfrac{\pi}{9} + \dfrac{k\pi}{3}$", [r"$x = \dfrac{\pi}{3} + k\pi$", r"$x = \dfrac{\pi}{9} + k\pi$", r"$x = \dfrac{\pi}{9} + \dfrac{2k\pi}{3}$"], r"$3x = \dfrac{\pi}{3} + k\pi$ ។"),
