    (r"ប្រព័ន្ធ $x + y = \dfrac{\pi}{2}$, $\sin x = \sin y$ មានចម្លើយមួយគឺ ៖", r"$x = y = \dfrac{\pi}{4}$", [r"$x = 0$, $y = \dfrac{\pi}{2}$", r"$x = \dfrac{\pi}{3}$, $y = \dfrac{\pi}{6}$", r"$x = \dfrac{\pi}{2}$, $y = 0$"], r"$\sin\dfrac{\pi}{4} = \sin\dfrac{\pi}{4}$ និង $\dfrac{\pi}{4} + \dfrac{\pi}{4} = \dfrac{\pi}{2}$ ។"),
    (r"ដោះស្រាយវិសមីការ $\sin x + \cos x > 0$ ក្នុង $[0, 2\pi)$ ៖", r"$0 \le x < \dfrac{3\pi}{4}$ ឬ $\dfrac{7\pi}{4} < x < 2\pi$", [r"$0 \le x < \dfrac{\pi}{2}$", r"$\dfrac{\pi}{4} < x < \dfrac{5\pi}{4}$", r"$\dfrac{3\pi}{4} < x < \dfrac{7\pi}{4}$"], r"$\sqrt{2}\sin\left(x + \dfrac{\pi}{4}\right) > 0$ ។"),
    (r"វិសមីការ $2\cos^2 x - \cos x - 1 \le 0$ សមមូល ៖", r"$-\dfrac{1}{2} \le \cos x \le 1$", [r"$\cos x \le -\dfrac{1}{2}$", r"$\cos x \ge 1$", r"$-1 \le \cos x \le \dfrac{1}{2}$"], r"$(2\cos x + 1)(\cos x - 1) \le 0$ ។"),
    (r"តម្លៃអប្បបរមានៃ $\sin x - \sqrt{3}\cos x$ គឺ ៖", r"$-2$", [r"$-1 - \sqrt{3}$", r"$-\sqrt{3}$", r"$0$"], r"$= 2\sin\left(x - \dfrac{\pi}{3}\right)$ ។"),
    (r"ដោះស្រាយ $\cos 2x - 3\cos x + 2 = 0$ ៖ គេបាន $\cos x$ ស្មើ ៖", r"$1$ ឬ $\dfrac{1}{2}$", [r"$2$ ឬ $1$", r"$-1$ ឬ $\dfrac{1}{2}$", r"$\dfrac{1}{2}$ តែមួយ"], r"$2\cos^2 x - 3\cos x + 1 = 0$ ។"),
    (r"ដោះស្រាយ $\sin x + \sin 3x = 0$ ៖ គេបំប្លែងជា ៖", r"$2\sin 2x\cos x = 0$", [r"$2\cos 2x\sin x = 0$", r"$\sin 4x = 0$", r"$2\sin 2x\sin x = 0$"], r"$\sin p + \sin q = 2\sin\dfrac{p + q}{2}\cos\dfrac{p - q}{2}$ ។"),
    (r"ចម្លើយនៃ $\sin x\cos x = \dfrac{1}{4}$ គឺ ៖", r"$x = \dfrac{\pi}{12} + k\pi$ ឬ $x = \dfrac{5\pi}{12} + k\pi$", [r"$x = \dfrac{\pi}{6} + k\pi$", r"$x = \dfrac{\pi}{12} + 2k\pi$", r"$x = \dfrac{\pi}{4} + k\pi$"], r"$\sin 2x = \dfrac{1}{2}$ ៖ $2x = \dfrac{\pi}{6} + 2k\pi$ ឬ $\dfrac{5\pi}{6} + 2k\pi$ ។"),
